define(['jquery','mage/translate','mage/validation'],function($,$t){'use strict';return function(target){return target.extend({initialize:function(){this._super();this.setupEnhancedValidation();return this;},setupEnhancedValidation:function(){var self=this;setTimeout(function(){self.addPhoneValidation();self.addAddressValidation();self.addRealTimeValidation();self.addAutoCorrection();},1000);},addPhoneValidation:function(){$.validator.addMethod('validate-algeria-phone',function(value){if(!value){return true;}
var cleaned=value.replace(/[\s\-\(\)]/g,'');var pattern=/^0[567]\d{8}$/;return pattern.test(cleaned);},$t('Numéro de téléphone invalide. Format: 05XX XX XX XX ou 06XX XX XX XX'));$('input[name="telephone"]').addClass('validate-algeria-phone');$('input[name="telephone"]').on('input',function(){var value=$(this).val().replace(/\D/g,'');if(value.length>0){var formatted=value.substring(0,4);if(value.length>=5){formatted+=' '+value.substring(4,6);}
if(value.length>=7){formatted+=' '+value.substring(6,8);}
if(value.length>=9){formatted+=' '+value.substring(8,10);}
$(this).val(formatted);}});},addAddressValidation:function(){$.validator.addMethod('validate-algeria-address',function(value){if(!value){return false;}
var hasNumber=/\d/.test(value);var minLength=value.length>=10;return hasNumber&&minLength;},$t('Veuillez entrer une adresse complète (min. 10 caractères avec un numéro)'));$('input[name="street[0]"], textarea[name="street[0]"]').addClass('validate-algeria-address');},addRealTimeValidation:function(){var self=this;$('.checkout-index-index input, .checkout-index-index select, .checkout-index-index textarea').on('blur',function(){var $field=$(this);var $parent=$field.closest('.field');if($parent.hasClass('_error')){return;}
if($field.valid&&$field.valid()){$parent.addClass('_success');setTimeout(function(){$parent.removeClass('_success');},2000);}});self.addPlaceholderExamples();},addPlaceholderExamples:function(){$('input[name="telephone"]').attr('placeholder','Ex: 0555 12 34 56');$('input[name="street[0]"], textarea[name="street[0]"]').attr('placeholder','Ex: Rue Ben Boulaid, Cité 20 Août');$('input[name="firstname"]').attr('placeholder','Ex: Mohamed');$('input[name="lastname"]').attr('placeholder','Ex: Benali');},addAutoCorrection:function(){$('input[name="firstname"], input[name="lastname"]').on('blur',function(){var value=$(this).val();if(value){var corrected=value.toLowerCase().replace(/\b\w/g,function(l){return l.toUpperCase();});$(this).val(corrected);}});$('.checkout-index-index input[type="text"], .checkout-index-index textarea').on('blur',function(){var value=$(this).val();if(value){var cleaned=value.trim().replace(/\s+/g,' ');$(this).val(cleaned);}});$('input[name="postcode"]').on('blur',function(){var value=$(this).val();if(value){var cleaned=value.replace(/\D/g,'');if(cleaned.length===5){$(this).val(cleaned);}}});},showFieldHelp:function(fieldName,message){var $field=$('[name="'+fieldName+'"]').closest('.field');var $help=$field.find('.field-help');if($help.length===0){$help=$('<div class="field-help"></div>');$field.find('.control').append($help);}
$help.html(message).show();},validateForm:function(){var isValid=this._super();if(!isValid){var $firstError=$('.field._error').first();if($firstError.length){$('html, body').animate({scrollTop:$firstError.offset().top-100},500);$firstError.find('input, select, textarea').first().focus();}}
return isValid;}});};});